// @overview
// Efficiently computes the n-th element of the FibFib sequence:
// fibfib(0) = 0, fibfib(1) = 0, fibfib(2) = 1
// fibfib(n) = fibfib(n-1) + fibfib(n-2) + fibfib(n-3) for n > 2
//
// @param x {int} sequence index (n)
//
// @return {int} value of fibfib(n)
fibfib:{[x]
    if[x<3; :0 0 1 x];  // Direct lookup for base cases (0, 1, 2)

    a:0; b:0; c:1;      // fibfib(0), fibfib(1), fibfib(2)
