// @param x {int[]} Input integers
//
// @return {int} Minimal sum
minSubArraySum:{[x]
    if[count x = 0; -9223372036854775807]; // Handle empty input (though spec says non-empty)

    // Initialize current running sum and global minimum with the first element
    currentSum: first x;
    minSum: currentSum;

    // Iterate through the rest of the array
    // Logic: For each element, decide whether to extend the existing subarray
    // or start a new subarray at the current element.
    // Since we want the *minimum*, we take the minimum of (currentSum + elem) and elem.
    {[c; s; e]
        c: min[e; c + e];      // Update running sum ending at current element
        s: min[s; c];          // Update global minimum
        (c; s)
    } each (currentSum; minSum; 1_ x)
    }[x]

    minSum
    }
```

