//    A string S is considered to be good if and only if all parentheses in S
//    are balanced. For example: the string '(())()' is good, while the string
//    '())' is not.
//    Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.
//
// @param x {string} 1st parentheses string
// @param y {string} 2nd parentheses string
//
// @return {string} "Yes" or "No" if matching

// Helper: returns 1b if string s is balanced, 0b otherwise
is_balanced:{[s]
    // Map '(' to 1, ')' to -1, then compute running sum
    deltas: (1 -2 * (s = ")")); 
    // Condition 1: Total sum must be 0
    // Condition 2: Running minimum must be >= 0 (never drops below zero)
    (0 = sum deltas) and (0 <= min xprev 0;deltas)
    }

match_parens:{[x;y]
    // Check both concatenation orders: x then y, or y then x
    if[any is_balanced each (x,y; y,x); :`Yes];
    `No
    }
