// @param y {int[]} Second interval [start, end]
//
// @return {string} "YES" if intersection length is prime, else "NO"
intersection:{[x;y]
    // Calculate the intersection boundaries
    // Start of intersection is the maximum of the two starts
    // End of intersection is the minimum of the two ends
    s: max[x[0]; y[0]];
    e: min[x[1]; y[1]];

    // If start > end, there is no intersection
    if[s > e; : "NO"];

    // Length of the closed interval is (end - start + 1)
    len: (e - s) + 1;

    // Check if length is prime
    // Primes are integers > 1 with no divisors other than 1 and themselves
    // 0 and 1 are not prime
    isPrime: len > 1 and all[not (2 til len) | len];

    $[isPrime; "YES"; "NO"]
