    // Find indices; if a planet is not found, the result will be -1 (out of range)
    i:planets?x
    j:planets?y

    // If either is invalid (not found), return empty list
    if[not (0 <= i < count planets) or not (0 <= j < count planets)];
        ();

    // Ensure we always slice from the smaller index to the larger index
    start: min[i;j]
    end: max[i;j]

    // Slice between the two indices (exclusive of the endpoints)
    // If they are adjacent or the same, this returns an empty list
    planets[start+1] upsert end
}
